-- KAN-461. OSM batch 2 (owner, 2026-11-28): hairdressers and barbers from the August 2026 OSM
-- archive. 398 rows not served today: no name match against Overture + curated, and no
-- served hairdresser or barber within 50 m. Held, not written (179): same-kind neighbours,
-- docs/kan-461/osm-batch2-held.md. Gyms are not in this batch: a gym task is brand-specific
-- (KAN-364) and gyms without a chain need their own look first (owner, 2026-11-28).
-- Rejected origins are refused inside each INSERT.
-- Withdraw with: UPDATE curated_poi SET status = 'removed' WHERE import_run_id = 'kan461-osm-batch2-20261128';
) AS v WHERE NOT EXISTS (SELECT 1 FROM poi_source_correction c WHERE c.visible = 0 AND c.source = CASE v.column15 WHEN 'openstreetmap' THEN 'openstreetmap' WHEN 'osm' THEN 'openstreetmap' WHEN 'foursquare' THEN 'foursquare' WHEN 'foursquare_os_places' THEN 'foursquare' WHEN 'overture' THEN 'overture' END AND c.source_id = v.column16)
ON CONFLICT (origin_source, origin_id) WHERE origin_source IS NOT NULL AND origin_id IS NOT NULL DO NOTHING
ON CONFLICT (poi_id) DO NOTHING;

